(()=>{
 const readers=[...document.querySelectorAll('main > .audio-reader, .article-page > .audio-reader')];
 // Keep only the first visible canonical reader; remove unexpected duplicates generated by stale builds.
 readers.slice(1).forEach(r=>r.remove());
 const reader=readers[0]||document.querySelector('.audio-reader');if(!reader)return;
 if(!('speechSynthesis'in window)||!('SpeechSynthesisUtterance'in window)){reader.querySelector('.audio-status').textContent='BU TARAYICI SESLİ OKUMAYI DESTEKLEMİYOR';reader.querySelectorAll('button,select').forEach(x=>x.disabled=true);return}
 const synth=window.speechSynthesis,play=reader.querySelector('.audio-play'),pause=reader.querySelector('.audio-pause'),stop=reader.querySelector('.audio-stop'),rate=reader.querySelector('.audio-rate'),voice=reader.querySelector('.audio-voice'),status=reader.querySelector('.audio-status'),bar=reader.querySelector('.audio-reader-progress i');let voices=[],chunks=[],index=0,active=false,paused=false,run=0;
 const lang=reader.dataset.lang==='EN'?'en':'tr';
 const load=()=>{const list=synth.getVoices()||[];if(list.length)voices=list;const selected=voice.value;const matches=voices.filter(v=>String(v.lang||'').toLowerCase().startsWith(lang));const available=matches.length?matches:voices;voice.innerHTML='<option value="">Otomatik</option>'+available.map(v=>`<option value="${encodeURIComponent(v.name)}">${v.name} (${v.lang||'?'})</option>`).join('');if([...voice.options].some(o=>o.value===selected))voice.value=selected;if(!voices.length)status.textContent='SES MOTORU HAZIRLANIYOR';else if(!active)status.textContent=matches.length?'DİNLEMEYE HAZIR':`${lang==='tr'?'TÜRKÇE':'İNGİLİZCE'} SES BULUNAMADI • OTOMATİK`};
 load();[200,700,1600,3000].forEach(t=>setTimeout(load,t));if('onvoiceschanged'in synth)synth.onvoiceschanged=load;
 const text=()=>{const source=document.querySelector('#full-analysis')||document.querySelector('.article-layout');if(!source)return'';const c=source.cloneNode(true);c.querySelectorAll('script,style,button,select,.audio-reader,.article-tools,.policy-brief-print').forEach(x=>x.remove());return String(c.innerText||c.textContent||'').replace(/\s+/g,' ').trim()};
 const split=t=>{const ss=t.match(/[^.!?…]+[.!?…]+|[^.!?…]+$/g)||[t],out=[];let c='';for(const s of ss){const n=(c+' '+s).trim();if(n.length>300&&c){out.push(c);c=s.trim()}else c=n}if(c)out.push(c);return out};
 const selectedVoice=()=>{const n=decodeURIComponent(voice.value||'');return voices.find(v=>v.name===n)||voices.find(v=>String(v.lang||'').toLowerCase().startsWith(lang)&&v.localService)||voices.find(v=>String(v.lang||'').toLowerCase().startsWith(lang))||voices.find(v=>v.default)||voices[0]};
 const ui=m=>{status.textContent=m;pause.disabled=!active;stop.disabled=!active;pause.textContent=paused?'DEVAM ET':'DURAKLAT';bar.style.width=chunks.length?`${Math.min(100,index/chunks.length*100)}%`:'0%'};
 const speak=token=>{if(!active||paused||token!==run)return;if(index>=chunks.length){active=false;bar.style.width='100%';ui('OKUMA TAMAMLANDI');return}const u=new SpeechSynthesisUtterance(chunks[index]);u.lang=lang==='en'?'en-US':'tr-TR';u.rate=Number(rate.value)||1;const v=selectedVoice();if(v)u.voice=v;u.onstart=()=>ui(`OKUNUYOR • ${index+1}/${chunks.length}`);u.onend=()=>{if(token!==run)return;index++;setTimeout(()=>speak(token),100)};u.onerror=e=>{if(['canceled','interrupted'].includes(e.error))return;active=false;ui(`SES HATASI: ${String(e.error||'BİLİNMİYOR').toUpperCase()}`)};synth.speak(u);if(synth.paused)synth.resume()};
 play.onclick=()=>{run++;synth.cancel();load();const t=text();if(!t){ui('OKUNACAK METİN BULUNAMADI');return}chunks=split(t);index=0;active=true;paused=false;ui('SES HAZIRLANIYOR');const token=run;setTimeout(()=>speak(token),180)};
 pause.onclick=()=>{if(!active)return;if(paused||synth.paused){synth.resume();paused=false;ui(`OKUNUYOR • ${index+1}/${chunks.length}`)}else{synth.pause();paused=true;ui('DURAKLATILDI')}};
 stop.onclick=()=>{run++;synth.cancel();active=false;paused=false;index=0;ui('DİNLEMEYE HAZIR')};
 rate.onchange=()=>{if(active){run++;synth.cancel();const token=run;setTimeout(()=>speak(token),120)}};window.addEventListener('pagehide',()=>synth.cancel());
})();
